    def _build_transaction(
        self,
        ops: list[_Op],
        plan: list[_PlanEntry],
        target_order: list[CellId_t],
    ) -> Transaction:
        """Translate the queued internal ops into a wire ``Transaction``.

        Every transaction ends with a ``ReorderCells`` op carrying the
        full post-transaction cell ordering, so the frontend can settle
        ordering even when structural ops don't fully determine it.
        """
        # Final (formatted) code per cell, keyed by the id it lands on.
        planned_code: dict[CellId_t, str] = {
            entry.cell_id: entry.code
            for entry in plan
            if entry.code is not None
        }

        tx_ops: list[Op] = []
        for op in ops:
            if isinstance(op, _AddOp):
                tx_ops.append(
                    CreateCell(
                        cell_id=op.cell_id,
                        code=planned_code.get(op.cell_id, op.code),
                        name=op.name if op.name is not None else "",
                        config=op.config,
                        before=op.before,
                        after=op.after,
                    )
                )
            elif isinstance(op, _DeleteOp):
                tx_ops.append(DeleteCell(cell_id=op.cell_id))
            elif isinstance(op, _UpdateOp):
                target = op.new_cell_id or op.cell_id
                if op.code is not None:
                    tx_ops.append(
                        SetCode(
                            cell_id=target,
                            code=planned_code.get(target, op.code),
                        )
                    )
                if op.config is not None:
                    tx_ops.append(
                        SetConfig(
                            cell_id=target,
                            column=op.config.column,
                            disabled=op.config.disabled,
                            hide_code=op.config.hide_code,
                        )
                    )
                if op.name is not None:
                    tx_ops.append(SetName(cell_id=target, name=op.name))
            elif isinstance(op, _MoveOp):
                # Positioning is conveyed by the ReorderCells op below.
                pass

        tx_ops.append(ReorderCells(cell_ids=tuple(target_order)))
        return Transaction(ops=tuple(tx_ops), source="kernel")

